// sync.mjs — writes the wiring to work on ai-core with Claude Code and opencode from the sources in .ai/:
//   .claude/agents/<x>.md   .claude/skills/<n>/SKILL.md      Claude Code
//   .opencode/agent/<x>.md  .opencode/skill/<n>/SKILL.md     opencode
//   node .ai/sync.mjs           write them
//   node .ai/sync.mjs --check   exit 1 when they are out of date (part of the tests)
// The sources are .ai/agents and .ai/skills; the generated files carry a marker and are never edited by hand.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const AI = dirname(fileURLToPath(import.meta.url)), ROOT = join(AI, "..")
const MARK = "<!-- generated by `node .ai/sync.mjs` from .ai/ — edit the source there -->"

/** the front matter lines and the body of a source file */
function split(text) {
  const m = text.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  return m ? { fm: m[1].split("\n"), body: m[2] } : { fm: [], body: text }
}
const withMark = (fm, body) => `---\n${fm.join("\n")}\n---\n${MARK}\n${body.replace(/^\n+/, "")}`

export function expected() {
  const out = new Map()
  const adir = join(AI, "agents"), sdir = join(AI, "skills")
  for (const f of existsSync(adir) ? readdirSync(adir).filter((x) => x.endsWith(".md")).sort() : []) {
    const { fm, body } = split(readFileSync(join(adir, f), "utf-8"))
    out.set(`.claude/agents/${f}`, withMark(fm, body))
    // opencode: the same description as a subagent; a source without Edit / Write in its tools may not edit
    const tools = (fm.find((l) => l.startsWith("tools:")) ?? "").toLowerCase()
    const oc = [...fm.filter((l) => l.startsWith("description:")), "mode: subagent", ...(tools && !/\b(edit|write)\b/.test(tools) ? ["permission:", "  edit: deny"] : [])]
    out.set(`.opencode/agent/${f}`, withMark(oc, body))
  }
  for (const d of existsSync(sdir) ? readdirSync(sdir).sort() : []) {
    const f = join(sdir, d, "SKILL.md")
    if (!existsSync(f)) continue
    const { fm, body } = split(readFileSync(f, "utf-8"))
    for (const base of [".claude/skills", ".opencode/skill"]) out.set(`${base}/${d}/SKILL.md`, withMark(fm, body))
  }
  return out
}

const want = expected(), bad = []
for (const [rel, text] of want) {
  const p = join(ROOT, rel)
  if (!existsSync(p) || readFileSync(p, "utf-8") !== text) bad.push(rel)
}
if (process.argv.includes("--check")) {
  if (bad.length) { console.log(`out of date: ${bad.slice(0, 6).join(", ")}${bad.length > 6 ? ` … (${bad.length})` : ""} — node .ai/sync.mjs`); process.exit(1) }
  console.log(`up to date (${want.size} files)`); process.exit(0)
}
for (const rel of bad) { mkdirSync(dirname(join(ROOT, rel)), { recursive: true }); writeFileSync(join(ROOT, rel), want.get(rel)) }
console.log(`${bad.length ? `wrote ${bad.length}` : "nothing to write"} of ${want.size} files (.claude/, .opencode/)`)
